head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsDt = ""; // 조회조건 결산일자
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/

let acntclsDtArray = new Array();

///////// 2. 초기화 영역 /////////
/**
 *  화면이 최초 로드될때 실행되는 초기화 이벤트
 *  (초기 데이터 조회나 컴포넌트 설정)
 */
scwin.onpageload = function() {
    try {
        scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00208.onpageload" });
    }
};

/**
 *  현재 로딩된 페이지가 초기화되거나 종료될때(다른 화면으로 이동하거나 페이지를 닫기전) 발생하는 이벤트
 *  (주로 SPA(Single Page Application) 환경에서 전역 자원을 해제하거나 메모리 누수 방지)
 */
scwin.onpageunload = function() {

};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * 종업원현황 조회
 */
scwin.search = async function() {

    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!scwin.chkValid()) {
        return;
    }

    dma_employeeStatusInfoReq.set("kisCd", scwin.vKisCd);
    dma_employeeStatusInfoReq.set("acntclsDtList", acntclsDtArray);

    const sbmOptions = {
        id : "sbm_employeeStatus",
        action : "/api/listing/nice/company-status/employee-status",
        method : "get",
        ref : "dma_employeeStatusInfoReq",
        target : "dlt_employeeStatusListRes|append",
        gridview : "grd_empStat",
        isProcessMsg : false
    };
    const res = await await $c.sbm.executeDynamic(sbmOptions);
    dlt_employeeStatusListRes.setJSON(res.responseJSON.body);

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 *  화면 초기화
 */
scwin.init = function() {

    // 결산일자 조회
    $p.parent().frame_head.getWindow().scwin.fn_SrchAcntclsDt();
    // fn_Search();

};

/**
 *  데이터셋 초기화
 */
scwin.initDs = function() {
    dlt_employeeStatusListRes.setData([]);
};

/**
 *  조회조건 유효성 체크
 */
scwin.chkValid = function() {

    scwin.vKisCd = $p.parent().frame_head.getWindow().scwin.fn_GetKisCd();
    scwin.vAcntclsDt = $p.parent().frame_head.getWindow().scwin.fn_GetAcntclsDt();

    if (scwin.vKisCd === "" || scwin.vAcntclsDt === "") {
        return false;
    }

    return true;

};

/**
 * 그리드 헤더의 제목을 세팅
 */
scwin.setGrdHeaderNm = function(pArray) {

    acntclsDtArray = []; // 배열 초기화

    grd_empStat.setHeaderValue("h_EMP_CNT1", pArray[0].text);
    grd_empStat.setHeaderValue("h_EMP_CNT2", pArray[1].text);
    grd_empStat.setHeaderValue("h_EMP_CNT3", pArray[2].text);
    grd_empStat.setHeaderValue("h_EMP_CNT4", pArray[3].text);

    for (let i=0; i < pArray.length; i++) {
        acntclsDtArray.push(pArray[i].value);
    }

};

/**
 *  엑셀파일다운로드
 */
scwin.excelDownload = function() {

    if (dlt_employeeStatusListRes.getRowCount() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }

    const options = {
        fileName : "종업원현황",
        sheetName : "종업원현황"
    };

    const infoArray = {};

    $c.data.downloadGridViewExcel(grd_empStat, options, infoArray);

};
